using AppCondominio.SharedKernel;
namespace AppCondominio.Modules.SecurityOperations.Domain;
public enum VisitStatus{Authorized=0,CheckedIn=1,CheckedOut=2,Cancelled=3} public enum SecurityIncidentStatus{Open=0,Escalated=1,Resolved=2}
public sealed class VisitorAuthorization:AggregateRoot{private VisitorAuthorization(Guid id,Guid communityId,Guid hostPersonId,string visitorName,string document,string destination,DateTimeOffset validFrom,DateTimeOffset validTo):base(id){CommunityId=communityId;HostPersonId=hostPersonId;VisitorName=Req(visitorName);Document=Req(document);Destination=Req(destination);ValidFrom=validFrom;ValidTo=validTo;CreatedAtUtc=DateTimeOffset.UtcNow;}public Guid CommunityId{get;private set;}public Guid HostPersonId{get;private set;}public string VisitorName{get;private set;}public string Document{get;private set;}public string Destination{get;private set;}public DateTimeOffset ValidFrom{get;private set;}public DateTimeOffset ValidTo{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public VisitStatus Status{get;private set;}public DateTimeOffset? CheckedInAtUtc{get;private set;}public DateTimeOffset? CheckedOutAtUtc{get;private set;}public string? Gate{get;private set;}public static VisitorAuthorization Create(Guid communityId,Guid hostPersonId,string visitorName,string document,string destination,DateTimeOffset validFrom,DateTimeOffset validTo){if(communityId==Guid.Empty||hostPersonId==Guid.Empty||validTo<=validFrom)throw new ArgumentException("Invalid visitor authorization.");return new(Guid.NewGuid(),communityId,hostPersonId,visitorName,document,destination,validFrom,validTo);}public void CheckIn(DateTimeOffset at,string gate){if(Status!=VisitStatus.Authorized||at<ValidFrom||at>ValidTo)throw new InvalidOperationException("Visitor authorization is not valid for check-in.");Status=VisitStatus.CheckedIn;CheckedInAtUtc=at;Gate=Req(gate);}public void CheckOut(DateTimeOffset at){if(Status!=VisitStatus.CheckedIn||CheckedInAtUtc>at)throw new InvalidOperationException("Visitor is not checked in.");Status=VisitStatus.CheckedOut;CheckedOutAtUtc=at;}public void Cancel(){if(Status!=VisitStatus.Authorized)throw new InvalidOperationException("Only authorized visit can be cancelled.");Status=VisitStatus.Cancelled;}static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class SecurityIncident:AggregateRoot{private SecurityIncident(Guid id,Guid communityId,string type,string description,string location,string reportedBy):base(id){CommunityId=communityId;Type=Req(type);Description=Req(description);Location=Req(location);ReportedBy=Req(reportedBy);ReportedAtUtc=DateTimeOffset.UtcNow;}public Guid CommunityId{get;private set;}public string Type{get;private set;}public string Description{get;private set;}public string Location{get;private set;}public string ReportedBy{get;private set;}public DateTimeOffset ReportedAtUtc{get;private set;}public SecurityIncidentStatus Status{get;private set;}public string? Resolution{get;private set;}public static SecurityIncident Create(Guid communityId,string type,string description,string location,string reportedBy)=>communityId==Guid.Empty?throw new ArgumentException("Community required."):new(Guid.NewGuid(),communityId,type,description,location,reportedBy);public void Escalate(){if(Status!=SecurityIncidentStatus.Open)throw new InvalidOperationException("Only open incident can escalate.");Status=SecurityIncidentStatus.Escalated;}public void Resolve(string resolution){if(Status==SecurityIncidentStatus.Resolved)throw new InvalidOperationException("Incident already resolved.");Resolution=Req(resolution);Status=SecurityIncidentStatus.Resolved;}static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed record SecurityOperationsKpi(int ActiveVisits,int CheckedInVisitors,int OpenIncidents,int EscalatedIncidents);